program='''def transform(grid):
    cells = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 8}
    placements = []
    height, width = len(grid), len(grid[0])
    for r in range(height - 1):
        for c in range(width - 1):
            square = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if square <= cells:
                placements.append((square, 1))
            for missing, color in (((0, 0), 2), ((1, 0), 3), ((0, 1), 4), ((1, 1), 5)):
                tri = {(r + dr, c + dc) for dr in range(2) for dc in range(2) if (dr, dc) != missing}
                if tri <= cells:
                    placements.append((tri, color))
    by_cell = {cell: [] for cell in cells}
    for shape, color in placements:
        for cell in shape:
            by_cell[cell].append((shape, color))
    solution = None
    def search(remaining, chosen):
        nonlocal solution
        if not remaining:
            solution = chosen
            return True
        cell = min(remaining, key=lambda p: sum(shape <= remaining for shape, _ in by_cell[p]))
        for shape, color in by_cell[cell]:
            if shape <= remaining and search(remaining - shape, chosen + [(shape, color)]):
                return True
        return False
    search(cells, [])
    result = [[0 for _ in row] for row in grid]
    for shape, color in solution or []:
        for r, c in shape:
            result[r][c] = color
    return result
'''
